final class BuyReplacementSellFillEvaluation {
 private final BuyReplacementPositiveNetMarginCandidate source; private final double sellProbability; private final double sellExpectedHours; private final double sellUnitsPerHour; private final double sellWaitHours;
 BuyReplacementSellFillEvaluation(BuyReplacementPositiveNetMarginCandidate s,double p,double h,double u,double w){source=s;sellProbability=p;sellExpectedHours=h;sellUnitsPerHour=u;sellWaitHours=w;}
 int getBuyOffsetIndex(){return source.getBuyOffsetIndex();} double getBuyOffset(){return source.getBuyOffset();} int getBuyPrice(){return source.getBuyPrice();} int getExactRemainderQuantity(){return source.getExactRemainderQuantity();} long getTotalCost(){return source.getTotalCost();} double getBuyProbability(){return source.getBuyProbability();} double getBuyExpectedHours(){return source.getBuyExpectedHours();} double getBuyUnitsPerHour(){return source.getBuyUnitsPerHour();} double getBuyWaitHours(){return source.getBuyWaitHours();} int getSellOffsetIndex(){return source.getSellOffsetIndex();} double getSellOffset(){return source.getSellOffset();} int getSellPrice(){return source.getSellPrice();} long getRawSpreadPerItem(){return source.getRawSpreadPerItem();} int getTaxPerItem(){return source.getTaxPerItem();} long getNetMarginPerItem(){return source.getNetMarginPerItem();} long getTotalTax(){return source.getTotalTax();} long getTotalNetMargin(){return source.getTotalNetMargin();} double getSellProbability(){return sellProbability;} double getSellExpectedHours(){return sellExpectedHours;} double getSellUnitsPerHour(){return sellUnitsPerHour;} double getSellWaitHours(){return sellWaitHours;}
}
